package com.jotirling.service;
import com.jotirling.entity.*;
import com.jotirling.repository.*;
import jakarta.validation.constraints.*;
import jakarta.persistence.EntityManager;
import java.math.*;
import java.time.*;
import java.util.*;
import java.security.MessageDigest;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
@Service @Transactional public class SimplePaymentService {
 private final AccountPaymentRepository payments;private final OpeningBalanceRepository opening;private final OpeningBalanceChangeRepository changes;private final AccountRepository accounts;private final ShopOrderRepository orders;private final PaymentService legacy;private final NoticeRepository notices;private final EntityManager em;private final PaymentClaimRepository oldClaims;
 public SimplePaymentService(AccountPaymentRepository p,OpeningBalanceRepository b,OpeningBalanceChangeRepository c,AccountRepository a,ShopOrderRepository o,PaymentService l,NoticeRepository n,EntityManager e,PaymentClaimRepository oc){payments=p;opening=b;changes=c;accounts=a;orders=o;legacy=l;notices=n;em=e;oldClaims=oc;}
 public record Input(@NotNull @DecimalMin("0.01") @Digits(integer=10,fraction=2) BigDecimal amount,@NotBlank @Pattern(regexp="[0-9a-fA-F-]{36}") String requestId){}
 public record Review(boolean approve,@NotNull @Size(max=500) String notes,boolean bankChecked){}
 public record OpeningInput(@NotNull @DecimalMin("0") @Digits(integer=10,fraction=2) BigDecimal amount){}
 public record View(Long id,Long customerId,String name,String phone,BigDecimal amount,String status,String notes,LocalDate paidDate,Instant createdAt,String requestId){}
 public record Balance(Long customerId,String name,String phone,BigDecimal opening,BigDecimal total,BigDecimal paid,BigDecimal remaining,BigDecimal advance,BigDecimal pending,List<View> history){}
 private ResponseStatusException bad(String s){return new ResponseStatusException(HttpStatus.BAD_REQUEST,s);}
 private Account customer(Long id){Account a=accounts.lockById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Customer not found"));if(!"CUSTOMER".equals(a.role))throw bad("Select a customer");return a;}
 private void admin(Account a){if(!"ADMIN".equals(a.role))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Admin only");}
 private View view(AccountPayment p){return new View(p.id,p.customer.id,p.customer.name,p.customer.phone,p.amount,p.status,p.notes,p.paidDate,p.createdAt,p.requestId);}
 private void notify(Account a,String title,String body){Notice n=new Notice();n.account=a;n.title=title;n.body=body;notices.save(n);}
 public Balance balance(Account a){BigDecimal due=BigDecimal.ZERO,paid=BigDecimal.ZERO;BigDecimal old=opening.findById(a.id).map(b->b.amount).orElse(BigDecimal.ZERO);for(ShopOrder o:orders.findByCustomerIdOrderByCreatedAtDesc(a.id)){if(PaymentService.chargeable(o.status)){due=due.add(o.total);paid=paid.add(legacy.summary(o).paid());}}List<AccountPayment> rows=payments.findByCustomerIdOrderByIdDesc(a.id);BigDecimal pending=BigDecimal.ZERO;for(AccountPayment p:rows){if("VERIFIED".equals(p.status))paid=paid.add(p.amount);if("PENDING".equals(p.status))pending=pending.add(p.amount);}due=due.add(old);BigDecimal net=due.subtract(paid);return new Balance(a.id,a.name,a.phone,old,due,paid,net.max(BigDecimal.ZERO),net.negate().max(BigDecimal.ZERO),pending,rows.stream().map(this::view).toList());}
 public List<Balance> all(Account a){admin(a);return accounts.findByRole("CUSTOMER").stream().map(this::balance).toList();}
 public void setOpening(Account a,Long id,OpeningInput in){admin(a);Account c=customer(id);OpeningBalance b=opening.findById(id).orElse(new OpeningBalance());OpeningBalanceChange change=new OpeningBalanceChange();change.customer=c;change.changedBy=a;change.oldAmount=b.amount==null?BigDecimal.ZERO:b.amount;change.newAmount=in.amount().setScale(2,RoundingMode.UNNECESSARY);changes.save(change);b.id=id;b.amount=change.newAmount;b.changedBy=a;b.changedAt=Instant.now();opening.save(b);notify(c,"जुन्या बाकीची नोंद अपडेट झाली","जुनी बाकी: INR "+b.amount+". Payments मध्ये जमा आणि शिल्लक पाहा.");}
 public View submit(Account a,Input in,byte[] proof,String type){Account c=customer(a.id);try{if(!UUID.fromString(in.requestId()).toString().equalsIgnoreCase(in.requestId()))throw bad("Invalid request");}catch(IllegalArgumentException e){throw bad("Invalid request");}BigDecimal amount=in.amount().setScale(2,RoundingMode.UNNECESSARY);String hash;try{hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(proof));}catch(Exception e){throw new IllegalStateException(e);}String sig=AuthService.hash(c.id+"|"+amount+"|"+hash);AccountPayment old=payments.findByRequestId(in.requestId()).orElse(null);if(old!=null){if(!old.customer.id.equals(c.id)||!old.signature.equals(sig))throw new ResponseStatusException(HttpStatus.CONFLICT,"Request already used");return view(old);}for(PaymentClaim prior:oldClaims.findAll()){if(prior.shopOrder.customer.id.equals(c.id)&&!"REJECTED".equals(prior.status)&&Arrays.equals(prior.screenshot,proof))throw new ResponseStatusException(HttpStatus.CONFLICT,"हा screenshot आधीच्या paymentमध्ये आहे. History पहा.");}String key=c.id+":"+hash;if(payments.existsByProofKey(key))throw new ResponseStatusException(HttpStatus.CONFLICT,"हा screenshot आधी पाठवला आहे. पुन्हा पैसे भरू नका; history पहा.");AccountPayment p=new AccountPayment();p.customer=c;p.amount=amount;p.requestId=in.requestId();p.signature=sig;p.proofKey=key;p.proof=proof;p.mediaType=type;p.paidDate=LocalDate.now(ZoneId.of("Asia/Kolkata"));payments.saveAndFlush(p);for(Account admin:accounts.findByRole("ADMIN"))notify(admin,"Payment तपासणी बाकी",c.name+" यांनी INR "+amount+" payment माहिती पाठवली. Payments मध्ये तपासा.");return view(p);}
 public View review(Account a,Long id,Review in){admin(a);AccountPayment p=payments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Payment not found"));customer(p.customer.id);em.refresh(p);if(!"PENDING".equals(p.status)){if((in.approve()&&"VERIFIED".equals(p.status))||(!in.approve()&&"REJECTED".equals(p.status)))return view(p);throw new ResponseStatusException(HttpStatus.CONFLICT,"Already reviewed");}if(in.approve()&&!in.bankChecked())throw bad("Check matching bank credit first");if(!in.approve()&&in.notes().isBlank())throw bad("Enter rejection reason");p.status=in.approve()?"VERIFIED":"REJECTED";p.notes=in.notes().trim();p.reviewedBy=a;p.reviewedAt=Instant.now();if(!in.approve())p.proofKey=null;payments.saveAndFlush(p);notify(p.customer,in.approve()?"Payment जमा झाले":"Payment तपशील नाकारले",in.approve()?"INR "+p.amount+" जमा नोंदवले. Payments मध्ये शिल्लक पाहा.":p.notes);return view(p);}
 public AccountPayment image(Account a,Long id){AccountPayment p=payments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Payment not found"));if(!"ADMIN".equals(a.role)&&!a.id.equals(p.customer.id))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Not your payment");return p;}
}
